export interface BankFloor extends FloorRule { system: System; cue?: RegExp }

let counter = 0;
export const BANK_FLOORS: FloorRule[] = NEW_ROWS.map(([sign, , tier, population, label, question]) => ({ id: `EXP-${String(++counter).padStart(3, '0')}`, sign, tier, population, label, question, source: SRC }));

const NEW_META: Record<string, Meta> = Object.fromEntries(NEW_ROWS.map(([sign, system, , , , , cue]) => [sign, { system, ...(cue ? { cue } : {}) }]));
const META: Record<string, Meta> = { ...EXISTING, ...NEW_META };

